// ❌ INVALID: Causes TypeScript error: Cannot use both select and include
// const invalid = await prisma.user.findMany({
//   select: { id: true },
//   include: { posts: true }
// });

// ✅ VALID: Nest relations directly inside select!
const users = await prisma.user.findMany({
  select: {
    id: true,
    name: true,
    // Relation loaded directly within select
    posts: {
      select: {
        id: true,
        title: true
      },
      where: { published: true }
    }
  }
});
